export type DigestGlance = { theme: string; momentum: string; outlook: string };

export type DigestSection = {
  number: number;
  name: string;
  slug: string;
  path: string;
  tagline: string;
  glance: DigestGlance[];
};

export type DigestArticle = {
  id: string;
  sectionNumber: number;
  section: string;
  sectionPath: string;
  title: string;
  lede: string;
  location: string;
  author: string;
  publishedAt: string;
  readTime: string;
  image: string;
  /* Body paragraphs in original order; the pull quote is rendered
     after paragraph index `quoteAfter`. */
  body: string[];
  quote: { text: string; by: string };
  quoteAfter: number;
  keyFacts: DigestKeyFact[];
  highlights: string[];
};

export function articleSlug(title: string) {
  return title
    .toLowerCase()
    .replace(/['’]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
}

